import{c as a,Q as t,j as o,m as i}from"./chunks/framework.DK3sgdKX.js";const u=JSON.parse('{"title":"统一场景编辑器 MVP","description":"","frontmatter":{},"headers":[],"relativePath":"SCENE_EDITOR_MVP.md","filePath":"SCENE_EDITOR_MVP.md","lastUpdated":1787221732000}'),s={name:"SCENE_EDITOR_MVP.md"};function l(d,e,n,c,r,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="统一场景编辑器-mvp" tabindex="-1">统一场景编辑器 MVP <a class="header-anchor" href="#统一场景编辑器-mvp" aria-label="Permalink to &quot;统一场景编辑器 MVP&quot;">​</a></h1><p>统一场景编辑器提供一个接近 Godot 工作流的 PyQt5 主窗口，并直接读写版本化 <code>pystg.scene</code> 文档。它不会替代现有纹理、立绘等专用工具，而是作为场景编排入口。</p><p>当前工作台已经包含 Scene、Inspector、2D Viewport、资源浏览器、Tools 插件入口和只读 Timeline；本页的“当前边界”描述仍然适用于 MVP 阶段。</p><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h2><p>安装开发依赖后，在项目根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scene_editor.py</span></span></code></pre></div><p>安装项目后也可以使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pystg-editor</span></span></code></pre></div><p>VS Code 任务列表中对应 <code>PythonSTG: Open Scene Editor</code>。</p><h2 id="窗口布局" tabindex="-1">窗口布局 <a class="header-anchor" href="#窗口布局" aria-label="Permalink to &quot;窗口布局&quot;">​</a></h2><ul><li>左侧 <strong>Scene</strong>：节点层级、添加、删除、重排和父子挂接。</li><li>中央 <strong>2D Viewport</strong>：画布网格、选择、拖动和网格吸附。</li><li>右侧 <strong>Inspector</strong>：节点名称和类型化属性。</li><li>底部 <strong>Output / Timeline</strong>：操作记录、预览进程输出和文档时间轴。</li></ul><p>第一批稳定节点类型：</p><ul><li><code>SceneRoot</code></li><li><code>Sprite</code></li><li><code>EnemySpawner</code></li><li><code>SpellCard</code></li></ul><p>场景树支持鼠标拖放，也提供显式的上移、下移、提升和缩进按钮。所有结构与 Inspector 修改都经过统一命令栈，可以 Undo/Redo。</p><h2 id="文件与保存" tabindex="-1">文件与保存 <a class="header-anchor" href="#文件与保存" aria-label="Permalink to &quot;文件与保存&quot;">​</a></h2><p>新场景默认保存到 <code>game_content/scenes/*.pystg.json</code>。编辑器只允许打开和保存 项目根目录以内的文件，写入使用临时文件和原子替换。</p><p>窗口标题中的 <code>*</code> 表示文档存在未保存修改。新建、打开和关闭前会检查未保存状态。</p><h2 id="预览" tabindex="-1">预览 <a class="header-anchor" href="#预览" aria-label="Permalink to &quot;预览&quot;">​</a></h2><p><code>Run / Preview</code>（F6）总是启动独立进程，不把 GLFW/ModernGL 窗口嵌入 Qt：</p><ul><li>选中配置了 <code>script</code> 的 <code>SpellCard</code> 时，启动真实符卡预览器。</li><li>选中其他节点时，启动 <code>metadata.preview_stage</code> 指定的正式关卡运行时，默认 <code>stage1</code>，并启用热重载。</li></ul><p>2D Viewport 是编辑视图，不宣称等同正式渲染结果。游戏画面和弹幕效果以独立预览 进程为准。</p><h2 id="当前边界" tabindex="-1">当前边界 <a class="header-anchor" href="#当前边界" aria-label="Permalink to &quot;当前边界&quot;">​</a></h2><ul><li>高密度子弹不会展开成 Scene Tree 节点。</li><li>时间轴当前只读，后续再接事件增删和拖动。</li><li>Assets 资源浏览器已接入，支持图片、脚本、JSON 以及 atlas 的 <code>sprites</code> / <code>animations</code> 子资源；子资源引用使用 <code>path.json#name</code>。</li><li><code>Sprite.texture</code> 可由资源浏览器选择图片或 sprite 子资源设置；选中 <code>SpellCard</code> 后也可以设置 Python <code>script</code>。</li><li>场景文档到任意 Python 关卡脚本的完整 runtime bridge 尚未实现；正式关卡预览 当前由 <code>preview_stage</code> 选择已有 Stage。</li></ul>',23)])])}const g=a(s,[["render",l]]);export{u as __pageData,g as default};
